CREATE TABLE skills (
    id UUID PRIMARY KEY,
    canonical_name VARCHAR(128) NOT NULL UNIQUE,
    category VARCHAR(64) NOT NULL
);

CREATE TABLE skill_aliases (
    id UUID PRIMARY KEY,
    skill_id UUID NOT NULL REFERENCES skills (id),
    alias VARCHAR(128) NOT NULL,
    CONSTRAINT uq_skill_aliases_alias UNIQUE (alias)
);

CREATE INDEX idx_skill_aliases_skill_id ON skill_aliases (skill_id);

CREATE TABLE analysis_skills (
    id UUID PRIMARY KEY,
    analysis_id UUID NOT NULL REFERENCES analyses (id) ON DELETE CASCADE,
    skill_id UUID NOT NULL REFERENCES skills (id),
    source VARCHAR(16) NOT NULL,
    priority VARCHAR(16),
    priority_ambiguous BOOLEAN NOT NULL DEFAULT FALSE,
    evidence TEXT,
    matched_term VARCHAR(128) NOT NULL,
    CONSTRAINT uq_analysis_skill_source UNIQUE (analysis_id, skill_id, source),
    CONSTRAINT chk_analysis_skill_source CHECK (source IN ('RESUME', 'JOB')),
    CONSTRAINT chk_analysis_skill_priority CHECK (priority IS NULL OR priority IN ('REQUIRED', 'PREFERRED'))
);

CREATE INDEX idx_analysis_skills_analysis_id ON analysis_skills (analysis_id);

